import random
import pytest
from quicksort import quicksort_randomized, brute_force_sort


# ── Basic correctness ────────────────────────────────────────────────

class TestBasicSorting:
    def test_empty(self):
        assert quicksort_randomized([]) == []

    def test_single_element(self):
        assert quicksort_randomized([42]) == [42]

    def test_two_elements_sorted(self):
        assert quicksort_randomized([1, 2]) == [1, 2]

    def test_two_elements_reversed(self):
        assert quicksort_randomized([2, 1]) == [1, 2]

    def test_two_equal(self):
        assert quicksort_randomized([3, 3]) == [3, 3]

    def test_already_sorted(self):
        arr = [1, 2, 3, 4, 5]
        assert quicksort_randomized(arr) == [1, 2, 3, 4, 5]

    def test_reverse_sorted(self):
        arr = [5, 4, 3, 2, 1]
        assert quicksort_randomized(arr) == [1, 2, 3, 4, 5]

    def test_general(self):
        assert quicksort_randomized([3, 1, 4, 1, 5, 9, 2, 6]) == [1, 1, 2, 3, 4, 5, 6, 9]


# ── Duplicates ───────────────────────────────────────────────────────

class TestDuplicates:
    def test_all_equal(self):
        arr = [7, 7, 7, 7, 7]
        assert quicksort_randomized(arr) == [7, 7, 7, 7, 7]

    def test_two_distinct_values(self):
        arr = [1, 0, 1, 0, 1, 0]
        assert quicksort_randomized(arr) == [0, 0, 0, 1, 1, 1]

    def test_many_duplicates_stress(self):
        random.seed(123)
        arr = [random.randint(0, 5) for _ in range(10_000)]
        assert quicksort_randomized(arr) == sorted(arr)


# ── Negative numbers ─────────────────────────────────────────────────

class TestNegatives:
    def test_all_negative(self):
        assert quicksort_randomized([-5, -1, -3, -2, -4]) == [-5, -4, -3, -2, -1]

    def test_mixed_sign(self):
        assert quicksort_randomized([-3, 0, 5, -1, 2]) == [-3, -1, 0, 2, 5]

    def test_negatives_and_duplicates(self):
        arr = [-1, -1, 0, 0, 1, 1, -2, -2]
        assert quicksort_randomized(arr) == [-2, -2, -1, -1, 0, 0, 1, 1]


# ── Non-mutation (returns a copy) ────────────────────────────────────

class TestNonMutation:
    def test_original_unchanged(self):
        original = [3, 1, 4, 1, 5]
        copy = original[:]
        quicksort_randomized(original)
        assert original == copy

    def test_return_value_independent(self):
        arr = [3, 1, 2]
        result = quicksort_randomized(arr)
        arr.append(99)
        assert 99 not in result


# ── Large / random inputs ────────────────────────────────────────────

class TestLargeInputs:
    def test_random_1000(self):
        random.seed(1)
        arr = [random.randint(-10_000, 10_000) for _ in range(1_000)]
        assert quicksort_randomized(arr) == sorted(arr)

    def test_random_10_000(self):
        random.seed(2)
        arr = [random.randint(0, 100_000) for _ in range(10_000)]
        assert quicksort_randomized(arr) == sorted(arr)

    def test_random_50_000(self):
        random.seed(3)
        arr = [random.randint(0, 1_000_000) for _ in range(50_000)]
        assert quicksort_randomized(arr) == sorted(arr)


# ── Specific patterns that stress partitioning ────────────────────────

class TestPartitioningStress:
    def test_sorted_large(self):
        """Tests worst-case for naive pivot (first element)."""
        arr = list(range(1_000))
        assert quicksort_randomized(arr) == arr

    def test_reverse_sorted_large(self):
        arr = list(range(1_000, 0, -1))
        assert quicksort_randomized(arr) == sorted(arr)

    def test_pipe_organ(self):
        """Ascending then descending: tests balanced partitioning."""
        arr = list(range(50)) + list(range(49, -1, -1))
        assert quicksort_randomized(arr) == sorted(arr)

    def test_few_unique_values(self):
        """Heavy duplicates — 3-way partitioning shines here."""
        random.seed(42)
        arr = [random.choice([1, 2, 3]) for _ in range(5_000)]
        assert quicksort_randomized(arr) == sorted(arr)


# ── Data types ───────────────────────────────────────────────────────

class TestDataTypes:
    def test_strings(self):
        arr = ["banana", "apple", "cherry", "date"]
        assert quicksort_randomized(arr) == ["apple", "banana", "cherry", "date"]

    def test_floats(self):
        arr = [3.14, 2.71, 1.41, 1.73]
        assert quicksort_randomized(arr) == [1.41, 1.73, 2.71, 3.14]

    def test_single_repeated_string(self):
        arr = ["a", "a", "a"]
        assert quicksort_randomized(arr) == ["a", "a", "a"]


# ── Stability is NOT guaranteed (document behavior) ──────────────────

class TestDeterminism:
    def test_same_result_across_runs(self):
        """Randomized pivot shouldn't affect correctness across runs."""
        random.seed(99)
        arr = [random.randint(0, 100) for _ in range(200)]
        results = {tuple(quicksort_randomized(arr)) for _ in range(50)}
        assert len(results) == 1


# ── Brute-force cross-check ──────────────────────────────────────────

class TestCrossCheck:
    def test_matches_brute_force_random(self):
        random.seed(7)
        arr = [random.randint(-50, 50) for _ in range(500)]
        assert quicksort_randomized(arr) == brute_force_sort(arr)

    def test_matches_brute_force_duplicates(self):
        random.seed(8)
        arr = [random.randint(0, 3) for _ in range(1_000)]
        assert quicksort_randomized(arr) == brute_force_sort(arr)


# ── Edge: performance shouldn't stack-overflow on sorted input ────────

class TestTailCallOptimization:
    def test_deep_recursion_sorted(self):
        """With tail-call optimization, sorted input should not blow the stack."""
        arr = list(range(10_000))
        result = quicksort_randomized(arr)
        assert result == arr

    def test_deep_recursion_reverse(self):
        arr = list(range(10_000, 0, -1))
        result = quicksort_randomized(arr)
        assert result == list(range(1, 10_001))
